import sys

data = sys.stdin.read().split()
r, c = int(data[0]), int(data[1])
g = [[int(data[2 + i * c + j]) for j in range(c)] for i in range(r)]


def go(i, j):
    if i == r - 1:
        return g[i][j]
    best = None
    for dj in (-1, 0, 1):
        nj = j + dj
        if 0 <= nj < c:
            v = go(i + 1, nj)
            if best is None or v < best:
                best = v
    return g[i][j] + best


print(min(go(0, j) for j in range(c)))

